function physics(i, dt){
  const lane = lanes[i], st = state[i];
  const Fs = lane.mus * M * G;   // 最大静摩擦
  const Fk = lane.muk * M * G;   // 滑动摩擦
  const maxX = (XMAX - X0) / PX_PER_M;
  let fric, moving;
  if (st.x >= maxX - 1e-9) {
    // 已顶到右侧边界：被挡住静止
    st.v = 0; st.running = false;
    if (st.stoppedAt === null) st.stoppedAt = st.x;
    fric = F(); moving = false;
  } else if (Math.abs(st.v) < 1e-6 && F() <= Fs) {
    // 静止：静摩擦与推力平衡（含未点击开始时）
    fric = Math.min(F(), Fs); moving = false;
    if (st.running) { st.running = false; }
  } else {
    // 运动：滑动摩擦，方向与运动相反
    st.running = true;
    fric = Fk;
    const a = (F() - fric) / M;
    st.v += a * dt;
    if (st.v <= 0 && F() <= Fk) {
      st.v = 0; st.running = false;
      if (st.stoppedAt === null) st.stoppedAt = st.x;
    } else {
      st.x += st.v * dt;
      if (st.x > maxX) st.x = maxX;
    }
    moving = st.running;
  }
  st.peakF = st.lastFric = fric;
  st.lastMoving = moving;
  return { fric, moving };
}

